    {kind="boss", floor=1029591, x=0.4141, y=0.7262, name="Mana Devourer", nameDE="Manaschlinger", nameFR="Dévoreur de mana", nameES="Devorador de maná", namePT="Devorador de Mana", nameRU="Пожиратель маны", nameKO="마나 포식자", nameCN="法力吞噬者", nameTW="法力吞噬者", encounters={3300}, note="In the courtyard north of the dome of the Violet Hold (place from Jurdi's video guide (beta): the minimap during the fight, matched with the game's minimap)", noteDE="Im Hof nördlich der Kuppel der Violetten Festung (Lage aus Jurdis Video-Guide (Beta): Minikarte im Kampf, per Bildvergleich mit der Spiel-Minikarte verortet)", noteFR="Dans la cour au nord du dôme du fort Pourpre (emplacement tiré du guide vidéo de Jurdi (bêta) : la minicarte pendant le combat, comparée à la minicarte du jeu)", noteES="En el patio al norte de la cúpula del Bastión Violeta (lugar según la guía en vídeo de Jurdi (beta): el minimapa durante el combate, comparado con el minimapa del juego)", notePT="No pátio ao norte da cúpula do Castelo Violeta (local tirado do guia em vídeo de Jurdi (beta): o minimapa durante a luta, comparado com o minimapa do jogo)", noteRU="Во дворе к северу от купола Аметистовой крепости (место из видеогайда Jurdi (бета): миникарта во время боя, сопоставленная с миникартой игры)", noteKO="보랏빛 요새 돔 북쪽의 안뜰 (위치는 Jurdi의 영상 가이드(베타) 기준: 전투 중 미니맵을 게임 미니맵과 대조)", noteCN="在紫罗兰监狱圆顶北边的庭院（位置来自Jurdi的视频攻略（测试版）：战斗时的小地图，与游戏小地图比对）", noteTW="在紫羅蘭堡圓頂北方的庭院（位置來自 Jurdi 的影片攻略（測試版）：戰鬥時的小地圖，與遊戲小地圖比對）"},
    {kind="boss", floor=1029591, x=0.5186, y=0.5534, name="Fel Ancient", nameDE="Teufelsurtum", nameFR="Ancien gangrené", nameES="Anciano vil", namePT="Anciente Vil", nameRU="Древень Скверны", nameKO="지옥의 고대정령", nameCN="邪能古树", nameTW="魔化古樹", encounters={3299}, note="In the middle of the city (Runeweaver Square): kill the treants first, then Magus Fansy Goodbringer south of the barrier lowers it", noteDE="Mitten in der Stadt (Der Runenweberplatz): erst die Treants töten, dann senkt Magus Fansy Goodbringer südlich der Barriere sie", noteFR="Au milieu de la ville (Place Tisserune) : tuez d'abord les tréants, puis Magus Fansy Goodbringer, au sud de la barrière, l'abaisse", noteES="En medio de la ciudad (Plaza Tejerruna): mata primero a los antárboles, después Magus Fansy Goodbringer, al sur de la barrera, la baja", notePT="No meio da cidade (Praça Fiarruna): mate primeiro os arvorecidos, depois Magus Fansy Goodbringer, ao sul da barreira, a baixa", noteRU="В центре города (Площадь Руноплета): сначала убейте древней, затем Magus Fansy Goodbringer к югу от барьера снимает его", noteKO="도시 한가운데 (룬위버 광장): 먼저 나무정령을 처치하면 장벽 남쪽의 Magus Fansy Goodbringer가 장벽을 내립니다", noteCN="在城市中央（鲁因广场）：先杀树人，然后屏障南边的Magus Fansy Goodbringer会撤下屏障", noteTW="在城市中央（織符者廣場）：先殺樹人，然後屏障南方的 Magus Fansy Goodbringer 會降下屏障"},
    {kind="boss", floor=1029591, x=0.6152, y=0.4187, name="Unstable Sentinel", nameDE="Instabile Schildwache", nameFR="Sentinelle instable", nameES="Centinela inestable", namePT="Sentinela Oscilante", nameRU="Нестабильный часовой", nameKO="불안정한 파수꾼", nameCN="不稳定的哨兵", nameTW="不穩定的哨兵", encounters={3302}, note="North-east of the city centre by the profession buildings; kill the Angry Tomes first (place from Jurdi's video guide (beta): the minimap during the fight, matched with the game's minimap)", noteDE="Nordöstlich der Stadtmitte bei den Berufsgebäuden; erst die Angry Tomes töten (Lage aus Jurdis Video-Guide (Beta): Minikarte im Kampf, per Bildvergleich mit der Spiel-Minikarte verortet)", noteFR="Au nord-est du centre-ville, près des bâtiments des métiers ; tuez d'abord les Tomes en colère (emplacement tiré du guide vidéo de Jurdi (bêta) : la minicarte pendant le combat, comparée à la minicarte du jeu)", noteES="Al noreste del centro de la ciudad, junto a los edificios de profesiones; mata primero a los Angry Tomes (lugar según la guía en vídeo de Jurdi (beta): el minimapa durante el combate, comparado con el minimapa del juego)", notePT="A nordeste do centro da cidade, junto aos prédios das profissões; mate primeiro os Angry Tomes (local tirado do guia em vídeo de Jurdi (beta): o minimapa durante a luta, comparado com o minimapa do jogo)", noteRU="К северо-востоку от центра города у зданий профессий; сначала убейте Злые фолианты (место из видеогайда Jurdi (бета): миникарта во время боя, сопоставленная с миникартой игры)", noteKO="도시 중심 북동쪽 전문기술 건물 옆; 먼저 Angry Tome을 처치하세요 (위치는 Jurdi의 영상 가이드(베타) 기준: 전투 중 미니맵을 게임 미니맵과 대조)", noteCN="在城市中心东北的专业建筑旁；先杀Angry Tome（位置来自Jurdi的视频攻略（测试版）：战斗时的小地图，与游戏小地图比对）", noteTW="在城市中心東北方的專業技能建築旁；先殺 Angry Tomes（位置來自 Jurdi 的影片攻略（測試版）：戰鬥時的小地圖，與遊戲小地圖比對）"},
    {kind="boss", floor=1029591, x=0.6738, y=0.5051, name="Mana Elemental", nameDE="Manaelementar", nameFR="Élémentaire de mana", nameES="Elemental de maná", namePT="Elemental de Mana", nameRU="Элементаль маны", nameKO="마나 정령", nameCN="法力元素", nameTW="法力元素", encounters={3301}, note="Called Arcanic Enigma in the game; east of the city centre with two Mana Phantoms; can also be done after the Shade", noteDE="Heißt im Spiel „Arkanes Mysterium“; östlich der Stadtmitte mit zwei Phantomen; geht auch nach dem Schemen", noteFR="Appelé Enigme arcanique dans le jeu ; à l'est du centre-ville avec deux Mana Phantoms ; peut aussi se faire après l'Ombre de l’archimage", noteES="En el juego se llama Enigma Arcano; al este del centro de la ciudad, con dos Mana Phantoms; también se puede hacer después del Shade", notePT="No jogo se chama Arcanic Enigma; a leste do centro da cidade, com dois Mana Phantoms; também pode ser feito depois do Vulto", noteRU="В игре называется «Чародейская энигма»; к востоку от центра города с двумя Mana Phantoms; можно убить и после Тени верховного мага", noteKO="게임에서는 신비한 수수께끼라는 이름입니다; 도시 중심 동쪽, Mana Phantom 2마리와 함께; 대마법사의 망령 다음에 해도 됩니다", noteCN="游戏中名为奥术之谜；在城市中心东边，伴有两个Mana Phantom；也可以在大法师之影之后再打", noteTW="遊戲中名為「秘法謎團」；在城市中心東方，有兩隻 Mana Phantoms；也可以在大法師之影之後再打"},
    {kind="boss", floor=1029591, x=0.5127, y=0.2196, name="Shade of the Archmage", nameDE="Schemen des Erzmagiers", nameFR="Ombre de l’archimage", nameES="Sombra del archimago", namePT="Vulto do Arquimago", nameRU="Тень верховного мага", nameKO="대마법사의 망령", nameCN="大法师之影", nameTW="大法師之影", encounters={3303}, note="Last boss: Archmage Modera at the bottom of the Violet Citadel opens the portal", noteDE="Letzter Boss: Erzmagierin Modera unten in der Violetten Zitadelle öffnet das Portal", noteFR="Dernier boss : l'Archimage Modera, en bas de la Citadelle Pourpre, ouvre le portail", noteES="Último jefe: la Archimaga Modera, en la parte baja de la Ciudadela Violeta, abre el portal", notePT="Último chefe: Arquimaga Modera, na parte de baixo da Cidadela Violeta, abre o portal", noteRU="Последний босс: Верховный маг Модера внизу Аметистовой цитадели открывает портал", noteKO="마지막 우두머리: 보랏빛 성채 맨 아래의 대마법사 모데라가 차원문을 엽니다", noteCN="最后一个首领：紫罗兰城堡底部的Archmage Modera会打开传送门", noteTW="最終首領：紫羅蘭城塞底部的大法師莫德菈會開啟傳送門"},
  },
  notes = {
    {floor=1029592, x=0.6836, y=0.5739, text="Way up: at Atrexis turn right into the channel to the east; at the end of the pipe a portal takes you up into the city, north of Krasus' Landing. Straight on leads to Lyn", textDE="Weg nach oben: bei Atrexis rechts in den Kanal nach Osten; am Rohrende bringt ein Portal hinauf in die Stadt, nördlich von Krasus' Landeplatz. Geradeaus ginge es zu Lyn", textFR="Montée : à Atrexis, tournez à droite dans le canal vers l'est ; au bout du tuyau, un portail vous fait monter dans la ville, au nord de l'Aire de Krasus. Tout droit mène à Lyn", textES="Camino hacia arriba: en Atrexis gira a la derecha hacia el canal del este; al final de la tubería un portal te sube a la ciudad, al norte del Alto de Krasus. Siguiendo recto se llega a Lyn", textPT="Caminho para cima: junto a Atrexis, vire à direita no canal para o leste; no fim do cano, um portal leva você para cima, até a cidade, ao norte da Plataforma de Krasus. Seguir em frente leva a Lyn", textRU="Путь наверх: у Атрексия поверните направо в канал на восток; в конце трубы портал переносит вас наверх в город, к северу от Площадки Краса. Прямо вы попадете к Лину", textKO="올라가는 길: 무덤 기사 아트렉시스에서 오른쪽으로 꺾어 동쪽 수로로 들어가세요; 배관 끝의 차원문이 크라서스 착륙장 북쪽 도시로 올려 보냅니다. 직진하면 외면받는 린에게 갑니다", textCN="上行路线：在墓穴骑士阿特雷克斯处右转进入东边的水道；管道尽头的传送门会把你送到上方的城市里，位于克拉苏斯平台以北。直走则通往被无视的琳恩", textTW="上行路線：在『墓地騎士』亞崔希斯處右轉進入往東的水道；管道盡頭的傳送門會帶你上到城市，位於卡薩斯平臺北方。直走則通往『忽視者』林恩"},
  },
  links = {
    {floor=1029592, x=0.7354, y=0.5461, to=1029591, label="P"},
    {floor=1029591, x=0.5449, y=0.754, to=1029592, label="P"},
  },
}

